const stock = slots.stock;
probe(Array.isArray(stock) && stock.length > 0, "the stock sheet must be a non-empty list");
let current = stock;
// stage 1: removeBelow
const kept0 = stock.filter((value) => value < slots.threshold);
probe(kept0.length > 0 && kept0.length < stock.length, "the filter must keep some readings and drop some");
current = kept0;
// stage 2: sum
const total1 = current.reduce((sum, value) => sum + value, 0);
current = total1;
// stage 3: percentOf
const adjusted2 = (current * slots.pct) / 100;
current = adjusted2;
// stage 4: discount
const adjusted3 = current - slots.discount * 100;
