function buildPath(head, edges) {
  const stack = [head];
  let previous = null;
  while (stack.length > 0) {
    const current = stack.shift();
    for (const edge of edges) {
      if (edge[0] === current || edge[1] === current) {
        previous = edge[0] === current ? edge[1] : edge[0];
        stack.push(previous);
      }
    }
  }
  return current + " " + previous + " " + (stack.length === slots.values.length ? "all records are sufficient" : "not all records are sufficient") + ".";
}
function canalPath(head, target) {
  const queue = [head];
  let reachable = false;
  while (queue.length > 0) {
    const current = queue.shift();
    if (current === target) {
      reachable = true;
      break;
    }
    for (const edge of slots.edges) {
      if (edge[0] === current || edge[1] === target) {
        queue.push(edge[1]);
      }
    }
  }
  return reachable;
}

