probe(Array.isArray(slots.nodes) && slots.nodes.length >= 2, "the node set must carry at least two nodes");
probe(Array.isArray(slots.edges) && slots.edges.length > 0, "the edge set must state at least one link");
probe(slots.edges.every((edge) => Number.isInteger(edge[0]) && Number.isInteger(edge[1])), "every link must connect two whole nodes");
const adjacency = new Map();
slots.nodes.forEach((node) => {
  probe(!adjacency.has(node), "a node must appear exactly once in the edge set");
  adjacency.set(node, []);
});
slots.edges.forEach((edge, index) => {
  if (edge[0] !== edge[1]) {
    probe(!adjacency.has(edge[1]), "every link must connect two different nodes");
    adjacency.get(edge[1]).push({ to: edge[0], index: index });
  }
});
const visited = new Set();
const queue = [];
let changed = true;
while (changed) {
  changed = false;
  while (queue.length > 0) {
    const node = queue.shift();
    for (const edge of adjacency.get(node) || []) {
