const direction = chosen < slots.nodes.length ? "left" : "right";
const connected = direction === "left" ? chosen < slots.nodes[0] : chosen > slots.nodes[0];
const main = (connected ? "Yes." : "No.") + " The largest remaining item is " + value + ", " + direction + " of " + slots.threshold + ".";
const suffix = renderCrossDomain(slots.crossDomain);
